// ---------- composition ----------
const shortName = (n) => n.split(' ')[0];
const handle = (n) => n.toLowerCase().replace(/[^a-z]+/g, '.').replace(/\.$/, '');
const navLinks = (k) => (k === 'tech'
  ? [{ label: 'Projects', url: '#work' }, { label: 'Stack', url: '#skills' }, { label: 'Contact', url: '#contact' }]
  : [{ label: 'Work', url: '#work' }, { label: 'About', url: '#about' }, { label: 'Contact', url: '#contact' }]);

function heroBlock(p, L, name, seed) {
  const words = String(p.s).split(',').map((x) => x.trim());
  if (p.k === 'tech' && L.dev && (L.hero === 'feature' || L.hero === 'center')) {
    const extra = (p.stack || []).flatMap(([, items]) => items.split(',').map((x) => x.trim()));
    return b('hero3d', { kicker: `Hi, I’m ${shortName(name)} 👋`, title: p.title, subtitle: p.sub, available: 'Open to new projects', words: [...new Set([...words, ...extra])].join(', '), buttonText: 'See my work', button2Text: 'Get in touch' }, { paddingY: 100, anchor: 'home' });
  }
  const layout = L.hero === 'feature' ? 'center' : L.hero;
  const image = L.heroImage === false && layout === 'center' ? '' : img(`${seed}-hero`, layout === 'cover' ? 1800 : 800, layout === 'cover' ? 1100 : 1000);
  return b('hero', { layout, kicker: p.role, title: p.title, subtitle: p.sub, image, buttonText: p.k === 'people' ? 'Book a session' : 'See my work', button2Text: 'Contact me' },
    { paddingY: layout === 'center' ? 130 : undefined, width: layout === 'cover' ? 'full' : '', align: layout === 'center' ? 'center' : '' });
}

function sections(p, L, name, seed, cat) {
  const names = NAMES.filter((n) => n !== name);
  const out = {};
  out.about = b('about', { title: 'About', text: p.about, image: L.narrow ? '' : img(`${seed}-about`, 700, 800) }, { anchor: 'about', width: L.narrow ? 'narrow' : '' });
  out.stats = b('stats', { items: p.st.map(([value, label]) => ({ value, label })) }, { align: 'center' });
  out.services = b('services', { title: 'What I do', items: p.sv.map(([title, desc]) => ({ title, desc })) }, { anchor: 'services' });
  out.exp = b('experience', { title: 'Experience', items: p.ex.map(([role, company, period, desc]) => ({ role, company, period, desc })) }, { width: 'narrow' });
  out.testimonials = b('testimonials', { title: 'Kind words', items: QUOTES[p.k].map(([quote, role], i) => ({ quote, name: names[(i * 7 + seed.length) % names.length], role, avatar: img(`${seed}-av${i}`, 120, 120) })) });
  out.cta = b('cta', { title: p.k === 'people' ? 'Ready when you are' : 'Have a project in mind?', text: 'I usually reply within a day.', buttonText: 'Get in touch' });
  out.contact = b('contact', { title: 'Get in touch', text: 'Tell me a little about what you need.', email: `hello@${handle(name).replace(/\./g, '')}.com` }, { anchor: 'contact' });

  const skillItems = String(p.s).split(',').map((x, i) => ({ name: x.trim(), level: 95 - i * 6 }));
  if (p.k === 'tech' && L.skills !== 'circles') out.skills = b('techstack', { title: 'Tech stack', display: L.dev ? 'icons' : 'chips', groups: (p.stack || [['Skills', p.s]]).map(([gname, items]) => ({ name: gname, items })) }, { anchor: 'skills' });
  else out.skills = b('skills', { title: 'Skills', display: L.skills, items: skillItems }, { anchor: 'skills', align: L.skills === 'circles' ? 'center' : '' });

  const projItems = p.pr.map(([title, desc, tags], i) => ({ title, desc, tags, image: img(`${seed}-p${i}`, 900, 600), url: '#' }));
  if (p.k === 'tech' && L.dev) {
    out.work = b('featured', { title: 'Featured projects', layout: L.cols === 3 ? 'grid' : 'alternating', items: projItems.map((it) => ({ ...it, image: img(`${seed}-f${it.title.length}`, 1200, 800), metric: '', liveUrl: 'https://example.com', githubUrl: 'https://github.com', shots: [] })) }, { anchor: 'work' });
  } else if (p.work === 'gallery') {
    out.work = b('gallery', { title: 'Selected work', columns: L.gallery === 'wide' ? 2 : 3, layout: L.gallery, images: [0, 1, 2, 3, 4, 5].map((i) => ({ src: img(`${seed}-g${i}`, 900, L.gallery === 'masonry' && i % 2 ? 1150 : 800), caption: L.gallery === 'wide' ? p.pr[i % p.pr.length][0] : '' })) }, { anchor: 'work' });
  } else {
    out.work = b('projects', { title: p.k === 'business' ? 'Results' : 'Selected work', columns: L.cols, items: projItems }, { anchor: 'work' });
  }

  const extra = p.k === 'tech' ? (L.dev ? 'github' : p.extra || 'certs') : p.extra;
  if (extra === 'github') out.extra = b('github', { title: 'On GitHub' });
  else if (extra === 'certs') out.extra = b('certs', { title: 'Certifications', items: [{ name: `${cat} certification`, issuer: 'Industry body', date: '2025', url: '', badge: '', kind: 'Certification' }, { name: 'Top performer award', issuer: p.ex[0][1], date: '2024', url: '', badge: '', kind: 'Award' }] });
  else if (extra === 'logos') out.extra = b('logos', { title: 'Trusted by' });
  else if (extra === 'video') out.extra = b('video', { title: 'Showreel' });
  else if (extra === 'pricing') out.extra = b('pricing', { title: 'Packages', items: p.sv.map(([s], i) => ({ name: s, price: ['₹9,000', '₹25,000', 'On request'][i], features: ['Consultation', 'Clear timeline', 'Revisions included'].slice(0, 3 - (i === 2 ? 1 : 0)).join('\n'), highlight: i === 1 })) });
  else if (extra === 'faq') out.extra = b('faq', { title: 'Questions', items: [{ q: 'How do we start?', a: 'Send a short message with what you need and your timeline. I reply within a day.' }, { q: 'Do you work remotely?', a: 'Yes, with clients anywhere. In person in Jaipur too.' }, { q: 'How do you charge?', a: 'Fixed quotes for most work, agreed before we begin.' }] });
  else if (extra === 'map') out.extra = b('map', { query: 'MI Road, Jaipur' });
  else if (extra === 'education') out.extra = b('education', { title: 'Education', items: [{ degree: p.k === 'people' && cat === 'Student' ? 'B.Tech, Computer Science' : 'Postgraduate degree', school: 'University of Rajasthan', period: cat === 'Student' ? '2023 – 2027' : '2008 – 2010' }] });
  return out;
}

function linkBio(p, L, name, seed) {
  return [
    b('image', { src: img(`${seed}-avatar`, 300, 300), width: 30, rounded: true }, { paddingY: 48 }),
    b('heading', { text: '@' + handle(name), level: '2' }, { align: 'center', paddingY: 0 }),
    b('text', { text: p.sub }, { align: 'center', paddingY: 8 }),
    b('links', { items: p.links.map(([label, note]) => ({ label, url: 'https://example.com', note })) }, { paddingY: 24 }),
    b('video', { title: '' }, { paddingY: 24 }),
    b('social', { items: [{ platform: 'Instagram', url: 'https://instagram.com' }, { platform: 'YouTube', url: 'https://youtube.com' }, { platform: 'TikTok', url: 'https://tiktok.com' }] }, { align: 'center' }),
    b('footer', { text: `© 2026 ${name}` }),
  ];
}

function compose(p, L, name, seed, cat) {
  if (p.k === 'linkbio') return linkBio(p, L, name, seed);
  const s = sections(p, L, name, seed, cat);
  const middle = ORDERS[L.order].filter((k) => s[k]).map((k) => s[k]);
  if (L.band) middle.forEach((blk, i) => { if (i % 2 === 1 && !['stats', 'cta'].includes(blk.type)) blk.style = { ...blk.style, bg: L.theme.surface }; });
  const blocks = [b('navbar', { logo: L.slug === 'midnight' || L.slug === 'brutal' ? '~/' + handle(name).split('.')[0] : name, links: navLinks(p.k) }), heroBlock(p, L, name, seed), ...middle];
  if (p.k === 'tech' && L.dev) blocks.push(b('chatbot', { name: `${shortName(name)}’s assistant`, knowledge: [{ keywords: 'stack, tech, tools, skills', answer: `I work with ${p.s}.` }, { keywords: 'projects, work, built', answer: p.pr.map((x) => `${x[0]}: ${x[1]}`).join('\n') }, { keywords: 'hire, available, contact, email, freelance', answer: 'Yes, I’m open to new projects. Use the contact form below.' }] }));
  blocks.push(b('footer', { text: `© 2026 ${name}` }));
  return blocks;
}

const catSlug = (c) => c.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

// One template per style for every category, minus the hand-made ones already in that category.
export function generateTemplates(categories, existing) {
  const out = [];
  categories.forEach((cat, ci) => {
    const p = PACKS[cat];
    if (!p) return;
    const need = Math.max(0, 20 - existing.filter((t) => t.category === cat).length);
    for (let i = 0; i < need; i++) {
      const L = STYLES[(i + ci) % STYLES.length];
      const name = NAMES[(i * 3 + ci) % NAMES.length];
      const slug = `${catSlug(cat)}-${L.slug}`;
      const extra = p.k === 'tech' ? { commandPalette: true } : {};
      out.push({
        slug,
        name: `${L.name} ${p.k === 'linkbio' ? 'Links' : p.role.split(' ').slice(-1)[0].replace(/^\w/, (c) => c.toUpperCase())}`,
        category: cat,
        premium: L.premium,
        description: L.desc,
        theme: theme({ ...L.theme, modeToggle: !!L.mode, ...extra, ...(p.k === 'linkbio' ? { maxWidth: 640 } : {}) }),
        blocks: () => compose(p, L, name, slug, cat),
      });
    }
  });
  return out;
}

// ---------- curvy styles: curved edges and background shapes from lib/shapes.js ----------
