function curvify(blocks, L) {
  const c = L.curves;
  const add = (blk, patch) => { if (blk && patch) blk.style = { ...blk.style, ...patch }; };
  add(blocks.find((blk) => blk.type === 'hero'), c.hero);
  add(blocks.find((blk) => blk.type === 'footer'), c.footer);
  blocks.filter((blk) => blk.type === 'cta').forEach((blk) => add(blk, c.cta));
  const middle = blocks.filter((blk) => !['navbar', 'hero', 'footer', 'cta', 'chatbot'].includes(blk.type));
  middle.forEach((blk, i) => { if (i % 2 === 1 && blk.type !== 'stats') add(blk, c.band); });
  return blocks;
}

// Six curvy templates for every category (link-in-bio pages excluded)
export function generateCurvyTemplates(categories) {
  const out = [];
  categories.forEach((cat, ci) => {
    const p = PACKS[cat];
    if (!p || p.k === 'linkbio') return;
    CURVY_STYLES.forEach((L, i) => {
      const name = NAMES[(i * 5 + ci + 7) % NAMES.length];
      const slug = `${catSlug(cat)}-${L.slug}`;
      out.push({
        slug,
        name: `${L.name} ${p.role.split(' ').slice(-1)[0].replace(/^\w/, (ch) => ch.toUpperCase())}`,
        category: cat,
        premium: L.premium,
        description: L.desc,
        theme: theme({ ...L.theme, ...(p.k === 'tech' ? { commandPalette: true } : {}) }),
        blocks: () => curvify(compose(p, L, name, slug, cat), L),
      });
    });
  });
  return out;
}
